SELECT fn_cp_import_case('biens-bien-vole-retrouve-en-vente-en-ligne', '{"slug": "biens-bien-vole-retrouve-en-vente-en-ligne", "title": "Elle reconnaît sa bague sur une annonce et a déjà contacté le vendeur", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": false, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 18 heures. Une femme se présente au commissariat, très agitée, expliquant avoir reconnu formellement sa bague de famille volée plusieurs semaines auparavant sur une annonce de vente en ligne, et précisant avoir déjà pris contact directement avec le vendeur pour évoquer cette découverte avant même de venir vous voir. Cette initiative personnelle, aussi compréhensible soit l''empressement de cette victime à récupérer un bien auquel elle est particulièrement attachée, risque d''avoir alerté ce vendeur et de compromettre ainsi la suite de cette affaire.\n\nCette situation, où la victime a déjà agi de sa propre initiative avant tout signalement formel, nécessite une action rapide pour éviter que ce vendeur, désormais informé de cette réclamation, ne fasse disparaître l''annonce ou ne se débarrasse du bien avant toute intervention officielle.\n\nCette configuration impose de faire cesser sans délai tout contact direct entre cette victime et ce vendeur potentiellement complice ou de bonne foi, tout en agissant avec célérité pour préserver les preuves de cette annonce avant qu''elle ne disparaisse.", "questions": [{"position": 1, "max_points": 5, "label": "Comment faites-vous cesser sans délai les contacts directs entre cette victime et ce vendeur ?", "hint": "L''initiative de cette victime, aussi légitime soit son émotion, doit être stoppée immédiatement pour ne pas compromettre davantage la suite de cette affaire.", "perfect": "Je lui demande fermement de cesser immédiatement tout contact supplémentaire avec ce vendeur, cette initiative personnelle risquant de compromettre la suite de l''enquête et l''éventuelle interpellation de cette personne.\n\nJe lui explique clairement les raisons de cette demande, notamment le risque que ce vendeur, désormais alerté, fasse disparaître l''annonce ou dissimule le bien avant toute intervention officielle.\n\nJe reste compréhensive face à son empressement, cette bague ayant une valeur sentimentale particulière qui explique sans excuser cette initiative personnelle prise avant son signalement formel.\n\nJe l''assure que la suite de cette affaire sera désormais prise en charge par les services compétents, cette garantie pouvant apaiser son besoin d''agir elle-même face à cette découverte.", "points": [{"position": 1, "label": "Demander fermement de cesser immédiatement tout contact avec le vendeur", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : risque de compromettre l''enquête et l''interpellation.", "groups": [{"position": 1, "keywords": ["contact cessé", "enquête compromise évitée", "interpellation préservée"]}]}, {"position": 2, "label": "Expliquer les raisons de cette demande de cessation", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Risque de disparition de l''annonce ou du bien.", "groups": [{"position": 1, "keywords": ["raisons expliquées", "annonce disparue", "bien dissimulé"]}]}, {"position": 3, "label": "Rester compréhensive face à son empressement sans l''excuser", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Valeur sentimentale expliquant sans excuser l''initiative.", "groups": [{"position": 1, "keywords": ["compréhension sans excuse", "valeur sentimentale", "initiative expliquée"]}]}, {"position": 4, "label": "L''assurer que la suite sera prise en charge par les services compétents", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Apaiser son besoin d''agir elle-même.", "groups": [{"position": 1, "keywords": ["prise en charge assurée", "besoin apaisé", "services compétents"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment agissez-vous avec célérité pour préserver les preuves de cette annonce avant qu''elle ne disparaisse ?", "hint": "L''annonce en ligne constitue une preuve fragile qui peut disparaître rapidement, cette préservation nécessitant une action immédiate et méthodique.", "perfect": "Je procède ou fais procéder sans délai à une capture de cette annonce, cette préservation immédiate étant essentielle face au risque de suppression rapide par ce vendeur désormais alerté.\n\nJe recueille l''ensemble des informations disponibles sur cette annonce, notamment l''identifiant du vendeur, sa localisation approximative et l''historique de ses éventuelles autres annonces sur cette plateforme.\n\nJe sollicite si possible et rapidement la plateforme d''hébergement de cette annonce, cette démarche pouvant permettre d''obtenir des informations complémentaires sur l''identité réelle de ce vendeur avant toute suppression.\n\nJe transmets ces éléments sans délai aux services compétents pour une exploitation rapide, cette urgence étant justifiée par le risque de disparition de ces preuves numériques.", "points": [{"position": 1, "label": "Procéder sans délai à une capture de cette annonce", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : risque de suppression rapide par le vendeur alerté.", "groups": [{"position": 1, "keywords": ["capture immédiate", "suppression rapide", "vendeur alerté"]}]}, {"position": 2, "label": "Recueillir l''ensemble des informations disponibles sur cette annonce", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Identifiant, localisation et historique du vendeur.", "groups": [{"position": 1, "keywords": ["informations recueillies", "identifiant du vendeur", "historique des annonces"]}]}, {"position": 3, "label": "Solliciter rapidement la plateforme d''hébergement de l''annonce", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Informations complémentaires avant toute suppression.", "groups": [{"position": 1, "keywords": ["plateforme sollicitée", "informations complémentaires", "avant suppression"]}]}, {"position": 4, "label": "Transmettre sans délai aux services compétents pour exploitation rapide", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Urgence justifiée par le risque de disparition des preuves.", "groups": [{"position": 1, "keywords": ["transmission sans délai", "exploitation rapide", "preuves préservées"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment établissez-vous le lien formel entre cette bague en vente et le vol dont elle a été victime ?", "hint": "Au-delà de la reconnaissance visuelle de la victime, des éléments objectifs doivent être recueillis pour établir formellement ce lien avec le vol initial.", "perfect": "Je recueille avec précision sa description initiale de cette bague telle qu''elle avait pu la fournir au moment du dépôt de sa plainte pour vol, cette comparaison étant essentielle pour établir ce lien de manière objective.\n\nJe m''assure qu''elle dispose d''éléments complémentaires d''identification, comme une photographie antérieure au vol ou une facture d''achat, ces preuves renforçant significativement la reconnaissance visuelle qu''elle affirme sur cette annonce.\n\nJe reste attentive à ne pas me fier uniquement à sa reconnaissance subjective, aussi convaincue soit-elle, cette identification méritant d''être objectivée par des éléments matériels complémentaires.\n\nJe consigne l''ensemble de ces éléments pour permettre aux services compétents d''établir formellement ce lien avant toute action à l''encontre de ce vendeur, qu''il soit lui-même auteur du vol ou simple intermédiaire de bonne foi.", "points": [{"position": 1, "label": "Recueillir sa description initiale fournie lors du dépôt de plainte", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : comparaison essentielle pour établir le lien objectivement.", "groups": [{"position": 1, "keywords": ["description initiale", "comparaison essentielle", "lien objectif"]}]}, {"position": 2, "label": "S''assurer qu''elle dispose d''éléments complémentaires d''identification", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Photographie antérieure ou facture d''achat.", "groups": [{"position": 1, "keywords": ["éléments complémentaires", "photographie antérieure", "facture d''achat"]}]}, {"position": 3, "label": "Ne pas se fier uniquement à sa reconnaissance subjective", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Identification objectivée par des éléments matériels.", "groups": [{"position": 1, "keywords": ["reconnaissance subjective", "objectivation nécessaire", "éléments matériels"]}]}, {"position": 4, "label": "Consigner pour établir formellement le lien avant toute action envers le vendeur", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Vendeur auteur du vol ou intermédiaire de bonne foi.", "groups": [{"position": 1, "keywords": ["lien formel établi", "avant action", "bonne foi possible"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-cambriolage-victime-en-etat-de-choc', '{"slug": "biens-cambriolage-victime-en-etat-de-choc", "title": "Elle répète que quelqu''un a dormi dans son lit", "theme_slug": "atteintes-biens", "difficulty": "moyen", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 25, "situation_text": "Il est 21 heures. Vous intervenez chez une femme victime d''un cambriolage constaté à son retour, cette dernière répétant en boucle, dans un état de choc manifeste, que quelqu''un a dormi dans son lit durant son absence, cette réalité la bouleversant bien davantage que l''inventaire des objets matériellement dérobés qu''elle peine pourtant à établir. Cette atteinte à l''intimité la plus profonde de son espace personnel, matérialisée par cette intrusion dans son lit lui-même, génère un retentissement psychologique qui dépasse largement le seul préjudice matériel habituellement associé à ce type d''infraction.\n\nCette victime, visiblement incapable de se concentrer sur l''inventaire pourtant nécessaire des objets disparus tant elle reste habitée par cette sensation de viol de son intimité la plus personnelle, nécessite une prise en charge qui reconnaisse pleinement cette dimension psychologique avant même d''aborder les aspects pratiques de cette intervention.\n\nCette situation impose de prendre le temps d''accueillir ce retentissement particulier avant de recueillir méthodiquement les éléments nécessaires au traitement de cette affaire, cette séquence adaptée respectant le rythme imposé par le choc de cette victime.", "questions": [{"position": 1, "max_points": 5, "label": "Comment accueillez-vous ce retentissement psychologique particulier avant d''aborder les aspects pratiques de cette intervention ?", "hint": "Cette atteinte à l''intimité doit être pleinement reconnue avant toute autre démarche, cette reconnaissance conditionnant la suite de la prise en charge.", "perfect": "J''accueille pleinement ce qu''elle exprime sur cette intrusion dans son lit, reconnaissant que cette dimension d''atteinte à son intimité la plus personnelle dépasse largement le seul préjudice matériel du cambriolage.\n\nJe ne minimise à aucun moment cette réaction en la ramenant prématurément vers le seul inventaire des objets disparus, cette précipitation risquant d''invalider l''ampleur du retentissement qu''elle exprime.\n\nJe reste attentive à son état de choc manifeste, en lui laissant le temps nécessaire pour exprimer ce qu''elle ressent avant d''aborder toute autre dimension de cette intervention.\n\nJe lui explique que cette réaction est parfaitement compréhensible face à ce type d''intrusion, cette validation pouvant l''aider à ne pas se sentir jugée pour l''intensité de son émotion face à un préjudice matériel objectivement limité.", "points": [{"position": 1, "label": "Accueillir pleinement l''expression de cette atteinte à l''intimité", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : dimension dépassant le seul préjudice matériel.", "groups": [{"position": 1, "keywords": ["atteinte à l''intimité", "accueil plein", "dépasse le matériel"]}]}, {"position": 2, "label": "Ne pas minimiser en la ramenant prématurément à l''inventaire", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Précipitation invalidant l''ampleur du retentissement.", "groups": [{"position": 1, "keywords": ["pas de minimisation", "pas de précipitation", "retentissement validé"]}]}, {"position": 3, "label": "Rester attentive à son état de choc en laissant le temps nécessaire", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Temps d''expression avant toute autre dimension.", "groups": [{"position": 1, "keywords": ["état de choc", "temps nécessaire", "expression respectée"]}]}, {"position": 4, "label": "Expliquer que cette réaction est parfaitement compréhensible", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Validation évitant qu''elle se sente jugée.", "groups": [{"position": 1, "keywords": ["réaction validée", "compréhensible", "pas de jugement"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment adaptez-vous le rythme de votre intervention à l''état de choc de cette victime ?", "hint": "Le rythme habituel d''une intervention pour cambriolage doit être adapté à l''état particulier de cette victime, cette flexibilité étant nécessaire pour un traitement respectueux.", "perfect": "Je prends le temps nécessaire avant de passer aux constatations habituelles, cette adaptation du rythme étant nécessaire face à un état de choc qui l''empêche momentanément de se concentrer sur les aspects pratiques.\n\nJe lui propose, si cela peut l''aider, de solliciter la présence d''un proche à ses côtés durant la suite de cette intervention, ce soutien pouvant faciliter progressivement le recueil des éléments nécessaires.\n\nJe reste attentive à ne pas la brusquer par des questions trop techniques ou pressantes, cette approche graduelle respectant le temps dont elle a besoin pour retrouver ses esprits.\n\nJe procède aux constatations indispensables avec délicatesse, en lui expliquant chaque étape pour qu''elle comprenne la nécessité de ces démarches malgré son état émotionnel actuel.", "points": [{"position": 1, "label": "Prendre le temps nécessaire avant de passer aux constatations habituelles", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : adaptation du rythme face au choc.", "groups": [{"position": 1, "keywords": ["temps nécessaire", "rythme adapté", "choc respecté"]}]}, {"position": 2, "label": "Proposer la présence d''un proche pour faciliter la suite", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Soutien facilitant progressivement le recueil.", "groups": [{"position": 1, "keywords": ["proche proposé", "soutien facilité", "recueil progressif"]}]}, {"position": 3, "label": "Ne pas la brusquer par des questions trop techniques ou pressantes", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Approche graduelle respectant son besoin de temps.", "groups": [{"position": 1, "keywords": ["pas de brusquerie", "approche graduelle", "besoin de temps"]}]}, {"position": 4, "label": "Procéder aux constatations indispensables avec délicatesse", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Expliquer chaque étape malgré l''état émotionnel.", "groups": [{"position": 1, "keywords": ["délicatesse", "étapes expliquées", "état émotionnel pris en compte"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous progressivement le recueil de l''inventaire nécessaire malgré ses difficultés de concentration ?", "hint": "L''inventaire reste nécessaire pour la suite de la procédure, mais son recueil doit être organisé de manière progressive et adaptée à l''état de cette victime.", "perfect": "J''explique avec tact pourquoi cet inventaire reste nécessaire pour la suite de la procédure, cette information pouvant l''aider à mobiliser progressivement son attention malgré son état de choc actuel.\n\nJe lui propose de procéder à cet inventaire en plusieurs étapes plutôt qu''en une seule fois, cette flexibilité méthodologique s''adaptant à ses difficultés de concentration actuelles.\n\nJe reste disponible pour qu''elle puisse compléter cet inventaire ultérieurement si certains éléments lui reviennent à l''esprit après mon départ, cette possibilité la soulageant de la pression de tout devoir se souvenir immédiatement.\n\nJe recueille en parallèle ses besoins immédiats, notamment si elle souhaite être accompagnée pour la nuit à venir compte tenu de cette atteinte particulière à son sentiment de sécurité dans son propre logement.", "points": [{"position": 1, "label": "Expliquer avec tact pourquoi l''inventaire reste nécessaire", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : mobiliser progressivement son attention.", "groups": [{"position": 1, "keywords": ["inventaire expliqué", "attention mobilisée", "tact nécessaire"]}]}, {"position": 2, "label": "Proposer de procéder à l''inventaire en plusieurs étapes", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Flexibilité s''adaptant aux difficultés de concentration.", "groups": [{"position": 1, "keywords": ["étapes multiples", "flexibilité méthodologique", "concentration respectée"]}]}, {"position": 3, "label": "Rester disponible pour compléter l''inventaire ultérieurement", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Soulager la pression de se souvenir immédiatement.", "groups": [{"position": 1, "keywords": ["disponibilité ultérieure", "pression soulagée", "complément possible"]}]}, {"position": 4, "label": "Recueillir ses besoins immédiats comme un accompagnement pour la nuit", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Sentiment de sécurité atteint dans son propre logement.", "groups": [{"position": 1, "keywords": ["besoins immédiats", "accompagnement pour la nuit", "sentiment de sécurité"]}]}]}]}'::jsonb);
SELECT fn_cp_import_case('biens-vol-a-l-etalage-mineur-non-accompagne', '{"slug": "biens-vol-a-l-etalage-mineur-non-accompagne", "title": "Il a treize ans et refuse de donner le numéro de ses parents", "theme_slug": "atteintes-biens", "difficulty": "facile", "is_free": true, "is_published": true, "status": "published", "year": 2026, "month": "Juillet", "total_points": 15, "estimated_minutes": 20, "situation_text": "Il est 17 heures. Vous êtes appelée dans un supermarché où le gérant retient un garçon de treize ans surpris en train de dérober des friandises, ce mineur non accompagné refusant catégoriquement de communiquer le numéro de téléphone de ses parents malgré vos demandes répétées, tandis que ce gérant, excédé par des vols répétés dans son établissement, exprime clairement son souhait de faire de ce jeune « un exemple » pour dissuader d''autres tentatives similaires. Cette configuration, où l''attente du commerçant en matière de fermeté entre en tension directe avec la protection due à ce mineur en raison de son statut, nécessite un traitement qui ne cède à aucune de ces deux pressions contradictoires.\n\nCe refus de ce jeune de communiquer les coordonnées de ses parents, qui peut traduire une peur de leur réaction ou une situation familiale plus complexe qu''il ne souhaite pas révéler, mérite d''être exploré avec la délicatesse appropriée plutôt que d''être traité comme un simple entêtement à vaincre par la fermeté.\n\nCette situation impose de traiter ce mineur selon son statut protecteur, sans céder à l''attente du gérant d''un traitement exemplaire qui ne correspondrait pas au cadre approprié pour un jeune de cet âge, tout en recherchant avec tact les raisons de ce refus de contact avec sa famille.", "questions": [{"position": 1, "max_points": 5, "label": "Comment traitez-vous ce mineur selon son statut protecteur sans céder à l''attente du gérant d''un traitement exemplaire ?", "hint": "L''exaspération légitime du gérant ne doit pas influencer le traitement de ce mineur, qui reste soumis à un cadre protecteur spécifique en raison de son âge.", "perfect": "Je reste factuelle et calme face à l''exaspération de ce gérant, ce traitement de ce mineur devant respecter le cadre protecteur qui lui est dû en raison de son âge, indépendamment de la fermeté que ce commerçant souhaiterait voir appliquée.\n\nJe lui explique clairement que je ne peux pas faire de cet enfant un exemple destiné à dissuader d''autres tentatives, cette approche punitive ne correspondant pas au traitement approprié pour un mineur de cet âge.\n\nJe reste attentive à traiter ce jeune avec la considération due à son statut, sans dureté excessive qui ne ferait que répondre à l''attente du gérant plutôt qu''à l''intérêt réel de ce mineur.\n\nJe recueille néanmoins les éléments nécessaires relatifs à ce vol, cette rigueur restant appropriée sans pour autant sacrifier la protection due à cet enfant à la satisfaction de l''exaspération légitime mais mal orientée de ce commerçant.", "points": [{"position": 1, "label": "Rester factuelle et calme face à l''exaspération du gérant", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : cadre protecteur dû en raison de l''âge.", "groups": [{"position": 1, "keywords": ["factuelle et calme", "cadre protecteur", "exaspération non suivie"]}]}, {"position": 2, "label": "Expliquer qu''il ne peut être fait un exemple de cet enfant", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Approche punitive inappropriée pour un mineur de cet âge.", "groups": [{"position": 1, "keywords": ["pas d''exemple fait", "approche punitive écartée", "âge du mineur"]}]}, {"position": 3, "label": "Traiter ce jeune avec la considération due à son statut", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Sans dureté excessive répondant à l''attente du gérant.", "groups": [{"position": 1, "keywords": ["considération due", "pas de dureté excessive", "statut respecté"]}]}, {"position": 4, "label": "Recueillir les éléments nécessaires sans sacrifier la protection due", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Rigueur appropriée sans céder à l''exaspération mal orientée.", "groups": [{"position": 1, "keywords": ["rigueur appropriée", "protection non sacrifiée", "exaspération mal orientée"]}]}]}, {"position": 2, "max_points": 5, "label": "Comment explorez-vous avec délicatesse les raisons de son refus de communiquer les coordonnées de ses parents ?", "hint": "Ce refus mérite d''être exploré avec tact plutôt que d''être traité comme un simple entêtement, cette réaction pouvant révéler une situation plus complexe.", "perfect": "Je l''interroge avec douceur sur les raisons de ce refus, cette approche non intrusive pouvant progressivement l''amener à s''exprimer sur ce qui motive cette réticence à contacter sa famille.\n\nJe reste attentive à la possibilité qu''il craigne une réaction disproportionnée de ses parents face à ce vol, cette peur méritant d''être prise au sérieux sans pour autant renoncer à la nécessité de ce contact.\n\nJe reste également attentive à une possible situation familiale plus complexe qui expliquerait ce refus, comme des difficultés à la maison qu''il ne souhaite pas révéler dans ce contexte.\n\nJe lui explique avec bienveillance que ce contact avec ses parents reste néanmoins nécessaire compte tenu de son âge, cette information étant transmise sans dramatiser excessivement la situation.", "points": [{"position": 1, "label": "L''interroger avec douceur sur les raisons de ce refus", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : approche non intrusive facilitant l''expression.", "groups": [{"position": 1, "keywords": ["interrogation douce", "approche non intrusive", "expression facilitée"]}]}, {"position": 2, "label": "Rester attentive à une possible crainte d''une réaction disproportionnée", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Peur prise au sérieux sans renoncer au contact nécessaire.", "groups": [{"position": 1, "keywords": ["crainte de réaction", "peur prise au sérieux", "contact maintenu"]}]}, {"position": 3, "label": "Rester attentive à une possible situation familiale plus complexe", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Difficultés à la maison non révélées.", "groups": [{"position": 1, "keywords": ["situation familiale complexe", "difficultés non révélées", "attention particulière"]}]}, {"position": 4, "label": "Expliquer avec bienveillance que ce contact reste nécessaire", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Information transmise sans dramatiser.", "groups": [{"position": 1, "keywords": ["contact nécessaire expliqué", "bienveillance", "pas de dramatisation"]}]}]}, {"position": 3, "max_points": 5, "label": "Comment organisez-vous concrètement la suite de cette prise en charge malgré son refus initial de coopérer sur ce point ?", "hint": "Malgré ce refus, une solution doit être trouvée pour organiser la suite de cette prise en charge conforme au statut protecteur de ce mineur.", "perfect": "Je recherche d''autres moyens d''identifier ce jeune ou de contacter sa famille, sans pour autant le brusquer par une insistance excessive sur ce refus initial de communiquer directement ces coordonnées.\n\nJe l''informe clairement que la procédure applicable à son statut de mineur nécessite nécessairement d''impliquer ses représentants légaux, cette information étant transmise de manière factuelle et rassurante.\n\nJe reste attentive à ne pas le laisser seul et sans protection dans l''attente de la résolution de cette situation, cette vigilance restant nécessaire compte tenu de son jeune âge.\n\nJe consigne avec précision l''ensemble de cette prise en charge, cette documentation étant nécessaire pour la suite du traitement de cette affaire conformément au cadre protecteur applicable à ce mineur.", "points": [{"position": 1, "label": "Rechercher d''autres moyens d''identifier ce jeune ou sa famille", "weight": 2.0, "is_required": true, "kind": "core", "explanation_md": "Cœur du cas : sans insistance excessive sur le refus initial.", "groups": [{"position": 1, "keywords": ["autres moyens recherchés", "identification alternative", "pas d''insistance excessive"]}]}, {"position": 2, "label": "L''informer que la procédure nécessite d''impliquer ses représentants légaux", "weight": 1.5, "is_required": true, "kind": "core", "explanation_md": "Information factuelle et rassurante.", "groups": [{"position": 1, "keywords": ["représentants légaux", "procédure informée", "factuelle et rassurante"]}]}, {"position": 3, "label": "Ne pas le laisser seul et sans protection dans l''attente", "weight": 1.0, "is_required": true, "kind": "core", "explanation_md": "Vigilance nécessaire compte tenu du jeune âge.", "groups": [{"position": 1, "keywords": ["pas seul sans protection", "vigilance nécessaire", "jeune âge"]}]}, {"position": 4, "label": "Consigner précisément cette prise en charge pour la suite", "weight": 0.5, "is_required": false, "kind": "bonus", "explanation_md": "Documentation conforme au cadre protecteur applicable.", "groups": [{"position": 1, "keywords": ["prise en charge consignée", "documentation nécessaire", "cadre protecteur"]}]}]}]}'::jsonb);